27	// CSS declarations for one property list, in canonical order.
28	pub fn css_decls(
29	    ctx: &Ctx,
30	    props: &[(String, Value)],
31	    vars: &mut Vec<String>,
32	    stroke_width_ctx: f64,
33	    text: bool,
34	) -> Result<Vec<(String, String)>, Diag> {
35	    let env = &ctx.sheet.env;
36	    let mut out = Vec::new();
37	    for &k in CSS_ORDER {
38	        let v = match get(props, k) {
39	            Some(v) => v,
40	            None => continue,
41	        };
42	        let span = v.span;
43	        match k {
44	            "fill" | "stroke" => {
45	                if let Some(t) = single_term(v) {
46	                    out.push((k.to_string(), color_css(t, vars, span)?));
47	                }
48	            }
49	            "color" => {
50	                if let Some(t) = single_term(v) {
51	                    let name = if text { "fill" } else { "color" };
52	                    out.push((name.to_string(), color_css(t, vars, span)?));
53	                }
54	            }
55	            "stroke-width" | "opacity" => {
56	                if let Some(x) = value_num(env, v) {
57	                    out.push((k.to_string(), f4(x)));
58	                }
59	            }
60	            "font-family" => out.push((k.to_string(), font_family_css(v))),
61	            "font-size" => {
62	                if let Some(x) = value_num(env, v) {
63	                    out.push((k.to_string(), format!("{}px", f4(x))));
64	                }
65	            }
66	            "font-weight" => out.push((k.to_string(), weight_css(v, vars, span)?)),
67	            "font-style" | "text-decoration" => {
68	                if let Some(s) = ident_of(v) {
69	                    out.push((k.to_string(), s.to_string()));
70	                }
71	            }
72	            "text-shadow" => out.push((k.to_string(), text_shadow_css(env, v, vars, span)?)),
73	            "stroke-style" => {
74	                if let Some(s) = ident_of(v) {
75	                    let sw = get(props, "stroke-width").and_then(|w| value_num(env, w)).unwrap_or(stroke_width_ctx);
76	                    if let Some(d) = dasharray(s, sw) {
77	                        out.push(("stroke-dasharray".to_string(), d));
78	                    }
79	                }
80	            }
81	            _ => {}
82	        }
83	    }
84	    Ok(out)
85	}
