377	// affine [a b c d e f]: x' = a x + c y + e, y' = b x + d y + f
378	fn mul(m: &[f64; 6], n: &[f64; 6]) -> [f64; 6] {
379	    [
380	        m[0] * n[0] + m[2] * n[1],
381	        m[1] * n[0] + m[3] * n[1],
382	        m[0] * n[2] + m[2] * n[3],
383	        m[1] * n[2] + m[3] * n[3],
384	        m[0] * n[4] + m[2] * n[5] + m[4],
385	        m[1] * n[4] + m[3] * n[5] + m[5],
386	    ]
387	}
388	
389	pub fn node_matrix(ctx: &Ctx, i: usize) -> [f64; 6] {
390	    let n = &ctx.nodes[i];
391	    let c = &ctx.comp[i];
392	    let t = [1.0, 0.0, 0.0, 1.0, n.x + c.translate.0, n.y + c.translate.1];
393	    if c.rotate != 0.0 {
394	        let a = c.rotate.to_radians();
395	        let r = [a.cos(), a.sin(), -a.sin(), a.cos(), 0.0, 0.0];
396	        mul(&t, &r)
397	    } else {
398	        t
399	    }
400	}
401	
402	fn bbox_walk(ctx: &Ctx, i: usize, parent: &[f64; 6], b: &mut [f64; 4]) {
403	    let n = &ctx.nodes[i];
404	    let m = mul(parent, &node_matrix(ctx, i));
405	    let (ow, oh) = crate::layout::outer(ctx, i);
406	    for (px, py) in [(-ow / 2.0, -oh / 2.0), (ow / 2.0, -oh / 2.0), (ow / 2.0, oh / 2.0), (-ow / 2.0, oh / 2.0)] {
407	        let x = m[0] * px + m[2] * py + m[4];
408	        let y = m[1] * px + m[3] * py + m[5];
409	        b[0] = b[0].min(x);
410	        b[1] = b[1].min(y);
411	        b[2] = b[2].max(x);
412	        b[3] = b[3].max(y);
413	    }
414	    if n.prim != Prim::Text {
415	        for &ch in &n.children {
416	            bbox_walk(ctx, ch, &m, b);
417	        }
418	    }
419	}
