596	// The node's outline elements (unindented), centred on its origin.
597	pub fn shape_lines(ctx: &Ctx, i: usize) -> Vec<String> {
598	    let n = &ctx.nodes[i];
599	    let c = &ctx.comp[i];
600	    let (w, h) = (n.w, n.h);
601	    let mut v = Vec::new();
602	    match n.prim {
603	        Prim::Block => {
604	            v.push(format!(
605	                "<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" rx=\"{}\" ry=\"{}\"/>",
606	                f4(-w / 2.0),
607	                f4(-h / 2.0),
608	                f4(w),
609	                f4(h),
610	                f4(c.radius),
611	                f4(c.radius)
612	            ));
613	        }
614	        Prim::Oval => {
615	            v.push(format!("<ellipse cx=\"0\" cy=\"0\" rx=\"{}\" ry=\"{}\"/>", f4(w / 2.0), f4(h / 2.0)));
616	        }
617	        Prim::Hex => {
618	            v.push(format!(
619	                "<polygon points=\"{},0 {},{} {},{} {},0 {},{} {},{}\"/>",
620	                f4(-w / 2.0),
621	                f4(-w / 4.0),
622	                f4(-h / 2.0),
623	                f4(w / 4.0),
624	                f4(-h / 2.0),
625	                f4(w / 2.0),
626	                f4(w / 4.0),
627	                f4(h / 2.0),
628	                f4(-w / 4.0),
629	                f4(h / 2.0)
630	            ));
631	        }
632	        Prim::Diamond => {
633	            v.push(format!(
634	                "<polygon points=\"0,{} {},0 0,{} {},0\"/>",
635	                f4(-h / 2.0),
636	                f4(w / 2.0),
637	                f4(h / 2.0),
638	                f4(-w / 2.0)
639	            ));
640	        }
641	        Prim::Slant => {
642	            let skew = prop_nums(ctx, i, "skew").first().copied().unwrap_or(15.0);
643	            let off = (skew.to_radians()).tan() * h / 2.0;
644	            v.push(format!(
645	                "<polygon points=\"{},{} {},{} {},{} {},{}\"/>",
646	                f4(-w / 2.0 + off),
647	                f4(-h / 2.0),
648	                f4(w / 2.0 + off),
649	                f4(-h / 2.0),
650	                f4(w / 2.0 - off),
651	                f4(h / 2.0),
652	                f4(-w / 2.0 - off),
653	                f4(h / 2.0)
654	            ));
655	        }
656	        Prim::Cyl => {
657	            let ry = h * 0.1;
658	            let rx = w / 2.0;
659	            let t = h / 2.0 - ry;
660	            v.push(format!(
661	                "<path d=\"M {} {} L {} {} A {} {} 0 0 0 {} {} L {} {} A {} {} 0 0 0 {} {} Z\"/>",
662	                f4(-rx),
663	                f4(-t),
664	                f4(-rx),
665	                f4(t),
666	                f4(rx),
667	                f4(ry),
668	                f4(rx),
669	                f4(t),
670	                f4(rx),
671	                f4(-t),
672	                f4(rx),
673	                f4(ry),
674	                f4(-rx),
675	                f4(-t)
676	            ));
677	            v.push(format!("<ellipse cx=\"0\" cy=\"{}\" rx=\"{}\" ry=\"{}\"/>", f4(-t), f4(rx), f4(ry)));
678	        }
679	        Prim::Line | Prim::Poly | Prim::Path => {
680	            let sw = c.stroke_width;
681	            match &n.geo {
682	                Some(crate::scene::Geo::Path(d)) => v.push(format!("<path d=\"{}\"/>", xml_escape(d))),
683	                Some(crate::scene::Geo::Points(pts)) => {
684	                    let mut pts = pts.clone();
685	                    let ms = prop_str(ctx, i, "marker-start").or_else(|| prop_str(ctx, i, "marker"));
686	                    let me = prop_str(ctx, i, "marker-end").or_else(|| prop_str(ctx, i, "marker"));
687	                    let mut marks = Vec::new();
688	                    if n.prim == Prim::Line && pts.len() >= 2 {
689	                        let k = pts.len();
690	                        if let Some(m) = ms.as_deref() {
691	                            if m != "none" {
692	                                let (p, q) = (pts[0], pts[1]);
693	                                let (lines, pull) = crate::markers::marker(m, p, (p.0 - q.0, p.1 - q.1), sw);
694	                                marks.extend(lines);
695	                                let d = crate::markers::unit((q.0 - p.0, q.1 - p.1));
696	                                pts[0] = (p.0 + d.0 * pull, p.1 + d.1 * pull);
697	                            }
698	                        }
699	                        if let Some(m) = me.as_deref() {
700	                            if m != "none" {
701	                                let (p, q) = (pts[k - 1], pts[k - 2]);
702	                                let (lines, pull) = crate::markers::marker(m, p, (p.0 - q.0, p.1 - q.1), sw);
703	                                marks.extend(lines);
704	                                let d = crate::markers::unit((q.0 - p.0, q.1 - p.1));
705	                                pts[k - 1] = (p.0 + d.0 * pull, p.1 + d.1 * pull);
706	                            }
707	                        }
708	                    }
709	                    let ps: Vec<String> = pts.iter().map(|(x, y)| format!("{},{}", f4(*x), f4(*y))).collect();
710	                    if n.prim == Prim::Poly {
711	                        v.push(format!("<polygon points=\"{}\"/>", ps.join(" ")));
712	                    } else if pts.len() == 2 {
713	                        v.push(format!(
714	                            "<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\"/>",
715	                            f4(pts[0].0),
716	                            f4(pts[0].1),
717	                            f4(pts[1].0),
718	                            f4(pts[1].1)
719	                        ));
720	                    } else {
721	                        v.push(format!("<polyline points=\"{}\"/>", ps.join(" ")));
722	                    }
723	                    let stroke_style = ctx.nodes[i].inline.iter().rev().find(|d| d.name == "stroke").map(|d| d.value.clone());
724	                    for m in marks {
725	                        let mut m = m;
726	                        if let Some(sv) = &stroke_style {
727	                            if let Some(t) = single_term(sv) {
728	                                let mut tmp = Vec::new();
729	                                if let Ok(col) = color_css(t, &mut tmp, sv.span) {
730	                                    if m.contains("lini-marker-open") {
731	                                        m = m.replacen("/>", &format!(" style=\"stroke: {}\"/>", col), 1);
732	                                    } else {
733	                                        m = m.replacen("/>", &format!(" style=\"fill: {}\"/>", col), 1);
734	                                    }
735	                                }
736	                            }
737	                        }
738	                        v.push(m);
739	                    }
740	                }
741	                None => {}
742	            }
743	        }
744	        _ => {}
745	    }
746	    v
747	}
