883	pub fn slot_rank(slot: &str) -> (usize, String) {
884	    if let Some(rest) = slot.strip_prefix("@define:") {
885	        let p = SLOT_ORDER.iter().position(|s| *s == "@define").unwrap();
886	        return (p, rest.to_string());
887	    }
888	    if let Some(rest) = slot.strip_prefix("@class:") {
889	        let p = SLOT_ORDER.iter().position(|s| *s == "@class").unwrap();
890	        return (p, rest.to_string());
891	    }
892	    match SLOT_ORDER.iter().position(|s| *s == slot) {
893	        Some(p) => (p, String::new()),
894	        None => (SLOT_ORDER.len(), slot.to_string()),
895	    }
896	}
