pub fn find(name: &str) -> Option<&'static TypeDef> {
    TYPES.iter().find(|t| t.name == name)
}

pub fn order_of(name: &str) -> usize {
    TYPES.iter().position(|t| t.name == name).unwrap_or(usize::MAX)
}
