#[derive(Clone, Debug)]
pub struct DefineModel {
    pub name: String,
    pub base: String,
    pub decls: Vec<Decl>,
    pub body: Option<Vec<Stmt>>,
    pub span: Span,
}

#[derive(Clone, Debug)]
pub struct ClassRule {
    pub name: String,
    pub decls: Vec<Decl>,
    pub span: Span,
    pub used: bool,
}

#[derive(Default)]
pub struct SheetModel {
    pub root: Vec<Decl>,
    pub vars: Vec<Decl>,
    pub env: Env,
    pub type_rules: Vec<(String, Vec<Decl>)>,
    pub defines: Vec<DefineModel>,
    pub classes: Vec<ClassRule>,
    pub id_rules: Vec<(String, Vec<Decl>)>,
    pub link_rules: Vec<Decl>,
    pub scoped_link_rules: Vec<(String, Vec<Decl>)>,
}

impl SheetModel {
    pub fn define(&self, name: &str) -> Option<&DefineModel> {
        self.defines.iter().find(|d| d.name == name)
    }
    pub fn type_rule(&self, name: &str) -> Vec<&Decl> {
        let mut out = Vec::new();
        for (n, ds) in &self.type_rules {
            if n == name {
                out.extend(ds.iter());
            }
        }
        out
    }
    pub fn class(&self, name: &str) -> Option<&ClassRule> {
        self.classes.iter().find(|c| c.name == name)
    }
}

#[derive(Clone, Debug)]
pub struct Node {
    pub prim: Prim,
    pub chain: Vec<String>, // most-derived first
    pub id: Option<String>,
    pub auto: bool,
    pub classes: Vec<String>,
    pub inline: Vec<Decl>,
    pub text: Option<String>,
    pub children: Vec<usize>,
    pub parent: Option<usize>,
    pub span: Span,
    pub props: HashMap<String, Value>,
    pub inline_props: HashMap<String, Value>,
    // layout results: rect size and centre relative to the parent's centre
    pub w: f64,
    pub h: f64,
    pub x: f64,
    pub y: f64,
    pub lines: Vec<String>,
    pub gutters: Vec<(f64, f64, f64, f64)>,
    pub scope: usize,
    pub geo: Option<Geo>,
    pub geo_off: (f64, f64),
}

#[derive(Clone, Debug)]
pub enum Geo {
    Points(Vec<(f64, f64)>),
    Path(String),
}

impl Node {
    pub fn new(prim: Prim, chain: Vec<String>, span: Span) -> Node {
        Node {
            prim,
            chain,
            id: None,
            auto: false,
            classes: vec![],
            inline: vec![],
            text: None,
            children: vec![],
            parent: None,
            span,
            props: HashMap::new(),
            inline_props: HashMap::new(),
            w: 0.0,
            h: 0.0,
            x: 0.0,
            y: 0.0,
            lines: vec![],
            gutters: vec![],
            scope: 0,
            geo: None,
            geo_off: (0.0, 0.0),
        }
    }
    pub fn is(&self, t: &str) -> bool {
        self.chain.iter().any(|c| c == t)
    }
}

