#[derive(Debug, Clone)]
pub enum Term {
    Num(f64, String, Span),
    Percent(f64, String, Span),
    Ident(String, Span),
    Str(String, Span),
    Hash(String, Span),
    Var(String, Span),
    Call(String, Vec<Expr>, Span),
    Group(Expr, Span),
    Tagged(Box<Term>, String, Span), // term ':' tag (draw segment names)
}

impl Term {
    pub fn span(&self) -> Span {
        match self {
            Term::Num(_, _, s)
            | Term::Percent(_, _, s)
            | Term::Ident(_, s)
            | Term::Str(_, s)
            | Term::Hash(_, s)
            | Term::Var(_, s)
            | Term::Call(_, _, s)
            | Term::Group(_, s)
            | Term::Tagged(_, _, s) => *s,
        }
    }
}

#[derive(Debug, Clone)]
pub enum Expr {
    Num(f64, Span),
    Percent(f64, Span),
    Ident(String, Span),
    Str(String, Span),
    Var(String, Span),
    Hash(String, Span),
    Call(String, Vec<Expr>, Span),
    Unary(String, Box<Expr>, Span),
    Bin(String, Box<Expr>, Box<Expr>, Span),
    Ternary(Box<Expr>, Box<Expr>, Box<Expr>, Span),
    Tuple(Vec<Expr>, Span),
    Block(Vec<(String, Expr)>, Box<Expr>, Span), // (a = 1; b = 2; expr)
}

impl Expr {
    pub fn span(&self) -> Span {
        match self {
            Expr::Num(_, s)
            | Expr::Percent(_, s)
            | Expr::Ident(_, s)
            | Expr::Str(_, s)
            | Expr::Var(_, s)
            | Expr::Hash(_, s)
            | Expr::Call(_, _, s)
            | Expr::Unary(_, _, s)
            | Expr::Bin(_, _, _, s)
            | Expr::Ternary(_, _, _, s)
            | Expr::Tuple(_, s)
            | Expr::Block(_, _, s) => *s,
        }
    }
}

