        if drawing {
            measure_part(ctx, ch);
        } else {
            crate::layout::measure(ctx, ch, None);
        }
        place(ctx, ch, 0.0, 0.0);
        // a feature beyond the break rides it with the far piece
        if let Some((along_x, _, b, shift)) = brk {
            let t = ctx.comp[ch].translate;
            if along_x && t.0 >= b - 1e-9 {
                ctx.nodes[ch].x -= shift;
            } else if !along_x && t.1 >= b - 1e-9 {
                ctx.nodes[ch].y -= shift;
            }
        }
    }
}

