            cmds.append('arc(%s, %s)' % (num(1, 15), random.choice([90, -90, 45, -45, 180, 135, -135, num(-300, 300, 1)])))
        elif c == 'arc3':
            dx, dy = num(-15, 15), num(-15, 15)
            r = ((dx * dx + dy * dy) ** 0.5) / 2 + num(0, 10)
            cmds.append('arc(%s, %s, %s)' % (dx, dy, round(r * random.choice([1, -1]), 2)))
        elif c == 'curve':
