        else:
            pat = ' pattern: radial(%d, %s);' % (random.randint(2, 6), num(2, 10))
    if k == 'rect':
        kids = ''
        if depth < 1 and random.random() < 0.5:
            kids = ' [\n' + '\n'.join(part(depth + 1) for _ in range(random.randint(1, 2))) + '\n]'
        return '|rect| { width: %s; height: %s;%s%s }%s' % (num(5, 40), num(5, 30), tr, pat, kids)
    if k == 'hole':
