    if k == 'centerline':
        return '|centerline| { points: %s %s, %s %s; }' % (num(-20, 0), num(-20, 20), num(0, 20), num(-20, 20))
    t = 'sketch' if k == 'sketch' else 'hidden'
    x0, y0 = num(-20, 0), num(-10, 0)
    d = 'move(%s, %s) right(%s) down(%s)' % (x0, y0, num(5, 30), num(3, 15))
