import struct, itertools
def fnvb(bs):
    h=0xcbf29ce484222325
    for b in bs:
        h^=b; h=(h*0x100000001b3)&0xFFFFFFFFFFFFFFFF
    return '%08x'%(((h>>32)^(h&0xFFFFFFFF))&0xFFFFFFFF)
