found=0
for t,a,s,c in T:
    parts={'a_le':struct.pack('<d',a),'a_be':struct.pack('>d',a),'s_le':struct.pack('<d',s),'s_be':struct.pack('>d',s),
           'c':c.encode(),'w_le':struct.pack('<d',0.75),'w_be':struct.pack('>d',0.75),
