#!/usr/bin/env python3
# random turned parts in drawings: compare original vs ours
import random, subprocess, os, tempfile, sys, difflib
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
N = int(sys.argv[2]) if len(sys.argv) > 2 else 100
def num(lo, hi, dec=1):
    return round(random.uniform(lo, hi), dec)
def profile():
    x0 = -num(20, 80, 0)
    r = num(3, 15, 0)
    cmds = ['move(%s, 0)' % x0, 'up(%s)' % r]
    tags = []
    if random.random() < 0.4:
        cmds.append('chamfer(%s)' % num(0.5, 1.5))
    x = x0
    steps = random.randint(1, 4)
    total = -2 * x0
    for k in range(steps):
        L = num(5, max(6, total / steps), 0)
        t = 'g%d' % k
        tags.append(t)
        cmds.append('right(%s):%s' % (L, t))
        x += L
        if k < steps - 1:
            dr = num(-4, 4, 0)
            if dr == 0 or r + dr < 2:
                dr = 2
            if random.random() < 0.3:
                cmds.append('fillet(%s)' % num(0.5, 1.0))
            cmds.append(('up(%s)' % dr) if dr > 0 else ('down(%s)' % -dr))
            r += dr
            if random.random() < 0.3:
                cmds.append('fillet(%s)' % num(0.5, 1.0))
    if random.random() < 0.4:
        cmds.append('chamfer(%s)' % num(0.5, 1.5))
    cmds.append('down(%s)' % r)
    return ' '.join(cmds), tags, x0, x
def src():
    d, tags, x0, x1 = profile()
    extra = ' revolve: x-axis;'
    if random.random() < 0.4 and tags:
        extra += ' thread: %s %s;' % (random.choice(tags), random.choice([1, 1.25, 1.5]))
    if random.random() < 0.3 and x1 - x0 > 30:
        a = round(x0 + (x1 - x0) * 0.3)
        b = round(x0 + (x1 - x0) * 0.6)
        if a < b:
            extra += ' break: %s %s;' % (a, b)
    kids = ''
    if random.random() < 0.3:
        kids = ' [\n  |hidden| { draw: move(%s, 2) left(5) line(-2, -2); mirror: x-axis; translate: %s 0; }\n]' % (0, round(x1))
    sc = random.choice(['', ' { scale: 0.5 }', ' { scale: 2 }'])
    lab = random.choice(['', ' "PART"'])
    return '|drawing|%s%s [\n|sketch#p| { draw: %s;%s }%s\n]' % (lab, sc, d, extra, kids)
tmp = tempfile.mkdtemp(prefix='fz3_')
bad = 0
for n in range(N):
    s = src()
    p = os.path.join(tmp, 'r_in.lini')
    open(p, 'w').write(s + '\n')
    r1 = subprocess.run(['/workspace/executable', 'r_in.lini'], capture_output=True, cwd=tmp)
    r2 = subprocess.run(['/tmp/bin-sketch/executable', 'r_in.lini'], capture_output=True, cwd=tmp)
    if (r1.stdout, r1.stderr, r1.returncode) != (r2.stdout, r2.stderr, r2.returncode):
        bad += 1
        if bad <= 6:
            print('### MISMATCH\n' + s)
            a = (r1.stderr + r1.stdout).decode().split('\n')
            b = (r2.stderr + r2.stdout).decode().split('\n')
            for line in list(difflib.unified_diff(a, b, n=0, lineterm=''))[2:14]:
                if '.lini-scope' in line and 'lini-node' not in line:
                    continue
                print('   ', line[:250])
print('mismatches %d / %d' % (bad, N))

