fn edges(base: &Shape, along_x: bool, brk: Option<(f64, f64)>) -> Vec<(f64, f64)> {
    let ax = |p: P| if along_x { p.x } else { p.y };
    let rad = |p: P| if along_x { p.y.abs() } else { p.x.abs() };
    let mut out: Vec<(f64, f64)> = Vec::new();
    let faces = end_faces(base, along_x);
    for s in &base.subs {
        if s.circle {
            continue;
        }
        let mut segs: Vec<Seg> = s.segs.clone();
        if s.closed && !s.end().near(s.start) {
            segs.push(Seg::Line { a: s.end(), b: s.start });
        }
        let n = segs.len();
        let joints = if s.closed { n } else { n.saturating_sub(1) };
        for k in 0..joints {
            let g1 = &segs[k];
            let g2 = &segs[(k + 1) % n];
            let (d1, d2) = match (g1.dir_end(), g2.dir_start()) {
                (Some(a), Some(b)) => (a, b),
                _ => continue,
            };
            let ang = d1.cross(d2).atan2(d1.dot(d2));
            if ang.abs() < 1e-6 {
                continue;
            }
            let v = g1.end();
            let r = rad(v);
            if r < 1e-9 {
                continue;
            }
            let x = ax(v);
            if faces.iter().any(|&(fx, fr)| (fx - x).abs() < 1e-9 && fr >= r - 1e-9) {
                continue;
            }
            let x = shifted(x, brk);
            if let Some(e) = out.iter_mut().find(|e| (e.0 - x).abs() < 1e-9) {
                e.1 = e.1.max(r);
            } else {
                out.push((x, r));
            }
        }
    }
    // edge lines draw in station order
    out.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    out
}
fn thread_lines(laid: &mut Laid, base: &Shape, seg: Option<&str>, pitch_px: f64, along_x: bool, brk: Option<(f64, f64)>) {
    let tag = base.tags().into_iter().find(|t| Some(t.name.as_str()) == seg);
    let g = match tag.map(|t| t.kind) {
        Some(sketch::TagKind::Seg(g)) => g,
        _ => return,
    };
    let (a, b) = (g.start(), g.end());
    let ax = |p: P| if along_x { p.x } else { p.y };
    let rad = |p: P| if along_x { p.y.abs() } else { p.x.abs() };
    let r = rad(a);
    // internal when the material lies beyond the surface (an inner subpath)
    let internal = is_internal(base, &g, along_x);
    let rr = if internal { r + THREAD_INTERNAL * pitch_px } else { r - THREAD_EXTERNAL * pitch_px };
    let (x1, x2) = (shifted(ax(a), brk), shifted(ax(b), brk));
    let mk = |x: f64, y: f64| if along_x { pt(x, y) } else { pt(y, x) };
    laid.thread = vec![(mk(x1, -rr), mk(x2, -rr)), (mk(x1, rr), mk(x2, rr))];
    if !internal {
        // the thread-end line, at the run's inner end
        let lo = base.subs.iter().flat_map(|s| s.segs.iter()).map(|g| ax(g.start()).min(ax(g.end()))).fold(f64::INFINITY, f64::min);
        let hi = base.subs.iter().flat_map(|s| s.segs.iter()).map(|g| ax(g.start()).max(ax(g.end()))).fold(f64::NEG_INFINITY, f64::max);
        let da = (ax(a) - lo).abs().min((ax(a) - hi).abs());
        let db = (ax(b) - lo).abs().min((ax(b) - hi).abs());
        let x0 = if da <= db { ax(b) } else { ax(a) };
        if end_faces(base, along_x).iter().any(|&(fx, fr)| (fx - x0).abs() < 1e-9 && fr >= r - 1e-9) {
            return;
        }
        let x = shifted(x0, brk);
        if let Some(e) = laid.edges.iter_mut().find(|e| (e.0 - x).abs() < 1e-9) {
            e.1 = e.1.max(r);
        } else {
            laid.edges.push((x, r));
        }
    }
}

