fn cross_runs(shape: &Shape, along_x: bool) -> Vec<(f64, f64, f64)> {
    let ax = |p: P| if along_x { p.x } else { p.y };
    let other = |p: P| if along_x { p.y } else { p.x };
    let mut out = Vec::new();
