        }
        for g in &segs {
            if let Seg::Line { a, b } = g {
                if (ax(*a) - ax(*b)).abs() < 1e-9 {
                    out.push((ax(*a), other(*a).min(other(*b)), other(*a).max(other(*b))));
                }
            }
        }
    }
    out
